const C1T = [[-1,2.752],[-0.75,2.927],[-0.5,2.704],[-0.25,2.281],[0,1.879],[0.25,1.563],[0.5,1.323],[0.75,1.141],[1,1.000]];
const c1Of = psi => { psi=Math.max(-1,Math.min(1,psi)); for(let i=0;i<C1T.length-1;i++){ const [a,ca]=C1T[i],[b,cb]=C1T[i+1]; if(psi>=a&&psi<=b) return ca+(cb-ca)*(psi-a)/(b-a); } return 1; };

const f = (x,p=2) => (x===null||x===undefined||!isFinite(x)) ? "–" : Number(x).toLocaleString("en-US",{minimumFractionDigits:p,maximumFractionDigits:p});
const f3 = x => f(x,3);
const sg = (x,p=1) => (x>=0?"+":"−")+f(Math.abs(x),p);
const refLabel = r => /^(\d|Table|Annex)/.test(r) ? "IS 800 "+r : r;
const strip = s => String(s).replace(/<sub>(.*?)<\/sub>/g,"$1").replace(/<sup>(.*?)<\/sup>/g,"^$1").replace(/<[^>]+>/g,"").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&amp;/g,"&");

// ---------- rectangle geometry ----------
// rect = [x0,x1,y0,y1]
function rprops(R){
  let A=0,Sx=0,Sy=0; R.forEach(r=>{ const a=(r[1]-r[0])*(r[3]-r[2]); A+=a; Sx+=a*(r[0]+r[1])/2; Sy+=a*(r[2]+r[3])/2; });
  const xc=Sx/A, yc=Sy/A; let Iz=0, Iy=0;
  R.forEach(r=>{ const b=r[1]-r[0], h=r[3]-r[2], a=b*h, dx=(r[0]+r[1])/2-xc, dy=(r[2]+r[3])/2-yc; Iz+=b*h**3/12+a*dy*dy; Iy+=h*b**3/12+a*dx*dx; });
  return {A,xc,yc,Iz,Iy};
}
// plastic modulus: axis "z" (horizontal axis, integrate along y) or "y" (vertical axis, integrate along x)
function zp(R, ax){
  const g = r => ax==="z" ? [r[2],r[3],r[1]-r[0]] : [r[0],r[1],r[3]-r[2]];
  const A=R.reduce((s,r)=>s+(r[1]-r[0])*(r[3]-r[2]),0);
  const below = t => R.reduce((s,r)=>{ const [c0,c1,w]=g(r); return s+w*Math.max(0,Math.min(t,c1)-c0); },0);
  let lo=Math.min(...R.map(r=>g(r)[0])), hi=Math.max(...R.map(r=>g(r)[1]));
  for(let i=0;i<80;i++){ const m=(lo+hi)/2; if(below(m)<A/2) lo=m; else hi=m; }
  const t=(lo+hi)/2;
  return R.reduce((s,r)=>{ const [c0,c1,w]=g(r), l1=Math.max(0,Math.min(t,c1)-c0), l2=Math.max(0,c1-Math.max(t,c0)); return s+w*l1*(t-c0-l1/2)+w*l2*(c1-l2/2-t); },0);
}
const iRects = (D,B,tw,tf,cx=0) => [[cx-B/2,cx+B/2,D/2-tf,D/2],[cx-tw/2,cx+tw/2,-D/2+tf,D/2-tf],[cx-B/2,cx+B/2,-D/2,-D/2+tf]];
// channel with the back of the web at x = xb; dir = +1 flanges point to +x, -1 to -x
const cRects = (D,B,tw,tf,xb=0,dir=1) => { const m=(a,b)=>dir>0?[xb+a,xb+b]:[xb-b,xb-a]; return [[...m(0,tw),-D/2,D/2],[...m(tw,B),D/2-tf,D/2],[...m(tw,B),-D/2,-D/2+tf]]; };

function rolledProps(fam, name, SEC){
  const F=FAMS[fam]; const row=(SEC[fam]||[]).find(r=>r[0]===name); if(!row||!F) return null;
  let s;
  if(F.k==="I"||F.k==="C"){
    const [nm,mass,A,D,B,tw,tf,R1,Iz,Iy,Zz,Zpz,It,Iw]=row, hw=D-2*tf;
    s={name:nm, kind:F.k, welded:false, mass, A:A*100, D, B, tw, tf, R1:R1||0, Iz:Iz*1e4, Iy:Iy*1e4, Zez:Zz*1e3, Zpz:Zpz*1e3, It:It?It*1e4:null, Iw:Iw?Iw*1e6:null, src:"IS 808 section table"};
    if(!s.It){ s.It=(2*B*tf**3+hw*tw**3)/3; s.itCalc=true; }
    if(!s.Iw){ const h=D-tf; s.Iw = F.k==="I" ? s.Iy*h*h/4 : tf*B**3*h*h/12*(3*B*tf+2*h*tw)/(6*B*tf+h*tw); s.iwCalc=true; }
    const R = F.k==="I" ? iRects(D,B,tw,tf) : cRects(D,B,tw,tf,0,1), rp=rprops(R), k=s.A/rp.A;
    s.cy = F.k==="C" ? rp.xc : B/2;
    s.Zey = F.k==="C" ? s.Iy/(B-s.cy) : s.Iy/(B/2);
    s.Zpy = zp(R,"y")*k; s.zpyCalc=true;
  } else if(F.k==="R"){
    const [nm,mass,A,D,B,t,Iz,Iy,Zz,Zpz]=row, Am=(B-t)*(D-t), p=2*((B-t)+(D-t));
    s={name:nm, kind:"R", welded:false, mass, A:A*100, D, B, tw:t, tf:t, t, R1:t, Iz:Iz*1e4, Iy:Iy*1e4, Zez:Zz*1e3, Zpz:Zpz*1e3, It:4*Am*Am*t/p, Iw:0, src:"IS 4923:1997 section table", itCalc:true};
    s.Zey=s.Iy/(B/2); s.Zpy=(D*B*B-(D-2*t)*(B-2*t)**2)/4; s.zpyCalc=true;
  } else {
    const [nm,mass,A,D,t,I,Z]=row;
    s={name:nm, kind:"O", welded:false, mass, A:A*100, D, B:D, tw:t, tf:t, t, R1:0, Iz:I*1e4, Iy:I*1e4, Zez:Z*1e3, Zpz:(D**3-(D-2*t)**3)/6, It:2*I*1e4, Iw:0, src:"IS 1161:2014 sizes"};
    s.Zey=s.Zez; s.Zpy=s.Zpz;
  }
  s.fam=fam; s.famT=F.t;
  return s;
}
// centroid offset e of each component from the built-up centroid, and the gap that gives it
function buGeom(c, arr, gap){
  const W=gap+2*c.B;
  let e, xb;
  if(c.kind==="I") e=gap/2+c.B/2;
  else if(arr==="toe") e=gap/2+c.B-c.cy;
  else e=gap/2+c.cy;
  return {W, e};
}
function gapFor(c, arr, ratio){ // gap so that ry = ratio x rz
  const e2=(ratio*ratio*c.Iz-c.Iy)/c.A; if(!(e2>0)) return 0;
  const e=Math.sqrt(e2);
  if(c.kind==="I") return 2*e-c.B;
  if(arr==="toe") return 2*(e-c.B+c.cy);
  return 2*(e-c.cy);
}
function buRects(c, arr, gap){
  if(c.kind==="I") { const g=buGeom(c,arr,gap); return [...iRects(c.D,c.B,c.tw,c.tf,-g.e),...iRects(c.D,c.B,c.tw,c.tf,g.e)]; }
  if(arr==="toe"){ const xo=gap/2+c.B; return [...cRects(c.D,c.B,c.tw,c.tf,-xo,1),...cRects(c.D,c.B,c.tw,c.tf,xo,-1)]; }
  return [...cRects(c.D,c.B,c.tw,c.tf,-gap/2,-1),...cRects(c.D,c.B,c.tw,c.tf,gap/2,1)];
}

function secProps(v, SEC){
  const F=FAMS[v.fam]; if(!F) return null;
  let s;
  if(v.fam==="WELD"){
    const D=v.wD, B=v.wB, tw=v.wtw, tf=v.wtf, hw=D-2*tf;
    if(!(D>0&&B>0&&tw>0&&tf>0&&hw>0&&tw<=B)) return null;
    const R=iRects(D,B,tw,tf), rp=rprops(R);
    s={name:`Welded I ${f(D,0)} × ${f(B,0)}, web ${f(tw,0)}, flanges ${f(tf,0)}`, kind:"I", welded:true, mass:rp.A*7850e-6, A:rp.A, D, B, tw, tf, R1:0, Iz:rp.Iz, Iy:rp.Iy,
      Zez:2*rp.Iz/D, Zpz:zp(R,"z"), Zey:2*rp.Iy/B, Zpy:zp(R,"y"), It:(2*B*tf**3+hw*tw**3)/3, Iw:rp.Iy*(D-tf)**2/4, src:"computed from the plate sizes", itCalc:true, iwCalc:true};
    s.fam="WELD"; s.famT=F.t;
  } else if(v.fam==="BUILT"){
    const c=rolledProps(v.bComp, v.bSec, SEC); if(!c || !(v.gap>=0)) return null;
    const arr = c.kind==="I" ? "side" : (v.bArr==="toe"?"toe":"btb"), g=buGeom(c,arr,v.gap);
    const Iy=2*(c.Iy+c.A*g.e*g.e);
    s={name:`2 × ${c.name}, ${arr==="side"?"side by side":arr==="toe"?"toes in":"back to back"}, gap ${f(v.gap,0)} mm`, kind:"BU", welded:false, comp:c, arr, gap:v.gap, e:g.e, W:g.W,
      mass:2*c.mass, A:2*c.A, D:c.D, B:g.W, tw:c.tw, tf:c.tf, R1:c.R1, Iz:2*c.Iz, Iy, Zez:2*c.Zez, Zpz:2*c.Zpz, Zey:Iy/(g.W/2), Zpy:2*c.A*g.e,
      It:2*c.It, Iw:Iy*(c.D-c.tf)**2/4, iwCalc:true, src:`${c.src}; built-up properties by parallel axes`};
    s.fam="BUILT"; s.famT=F.t;
  } else s=rolledProps(v.fam, v.sec, SEC);
  if(!s) return null;
  s.rz=Math.sqrt(s.Iz/s.A); s.ry=Math.sqrt(s.Iy/s.A);
  return s;
}

// ---------- classification for compression with or without bending (Table 2) ----------
function classify(sp, fy, P, hasM){
  const eps=Math.sqrt(250/fy), r=Math.max(0,(P*1e3/sp.A)/(fy/GM0)), lines=[];
  const pick=(x,l)=>x<=l[0]?0:x<=l[1]?1:x<=l[2]?2:3;
  let c;
  if(sp.kind==="O"){
    const dt=sp.D/sp.t, la=88*eps*eps;
    if(hasM){ const l=[42,52,146].map(k=>k*eps*eps); c=pick(dt,l); if(dt>la) c=3;
      lines.push(`Tube D/t = ${f(dt,2)}; bending limits 42ε² = ${f(l[0],1)}, 52ε² = ${f(l[1],1)}, 146ε² = ${f(l[2],1)}; axial limit 88ε² = ${f(la,1)} → ${CLS[c]}`); }
    else { c = dt<=la?2:3; lines.push(`Tube in axial compression, D/t = ${f(dt,2)}; limit 88ε² = ${f(la,1)} → ${c===2?"not slender":"slender"}`); }
    return {c, eps, r, lines};
  }
  const cs = sp.kind==="BU" ? sp.comp : sp, isC = cs.kind==="C";
  let b, kf, fl;
  if(sp.kind==="R"){ b=sp.B-3*sp.t; kf=[29.3,33.5,42]; fl=`Compression flange (internal), b = B − 3t = ${f(b,1)} mm`; }
  else { b = isC ? cs.B : cs.B/2; kf = sp.welded ? [8.4,9.4,13.6] : [9.4,10.5,15.7]; fl=`Flange outstand (${sp.welded?"welded":"rolled"}${sp.kind==="BU"?", each component":""}), b = ${isC?"b<sub>f</sub>":"b<sub>f</sub>/2"} = ${f(b,1)} mm`; }
  const t=sp.kind==="R"?sp.t:cs.tf, rf=b/t, lf=kf.map(k=>k*eps), cf=pick(rf,lf);
  lines.push(`${fl}; b/t = ${f(rf,2)}; limits ${kf[0]}ε = ${f(lf[0],2)}, ${kf[1]}ε = ${f(lf[1],2)}, ${kf[2]}ε = ${f(lf[2],2)} → ${CLS[cf]}`);
  const d = sp.kind==="R" ? sp.D-3*sp.t : (sp.welded ? sp.D-2*sp.tf : cs.D-2*(cs.tf+cs.R1)), tw=sp.kind==="R"?sp.t:cs.tw, rw=d/tw;
  let cw, wl;
  if(!hasM){ const l=42*eps; cw = rw<=l?2:3; wl=`Web in axial compression, d/t<sub>w</sub> = ${f(d,1)}/${f(tw,1)} = ${f(rw,2)}; limit 42ε = ${f(l,2)} → ${cw===2?"not slender":"slender"}`; }
  else {
    const m=42*eps, l=[Math.max(84*eps/(1+r),m), Math.max(105*eps/(1+1.5*r),m), Math.max(126*eps/(1+2*r),m)];
    cw=pick(rw,l); wl=`Web with axial force and bending, r<sub>1</sub> = r<sub>2</sub> = (P/A)/(f<sub>y</sub>/γ<sub>m0</sub>) = ${f3(r)}; d/t<sub>w</sub> = ${f(rw,2)}; limits 84ε/(1 + r<sub>1</sub>) = ${f(l[0],1)}, 105ε/(1 + 1.5r<sub>1</sub>) = ${f(l[1],1)}, 126ε/(1 + 2r<sub>2</sub>) = ${f(l[2],1)} (each ≥ 42ε) → ${CLS[cw]}`;
  }
  lines.push(wl);
  c = hasM ? Math.max(cf,cw) : (Math.max(cf,cw)===3?3:2);
  return {c, eps, r, lines};
}
function buckClass(sp, hollow){
  if(sp.kind==="R"||sp.kind==="O") return hollow==="hot" ? {z:"a",y:"a",why:"hot finished hollow section"} : {z:"b",y:"b",why:"cold formed hollow section"};
  if(sp.kind==="C") return {z:"c",y:"c",why:"channel"};
  if(sp.kind==="BU") return {z:"c",y:"c",why:"built-up member"};
  if(sp.welded) return sp.tf<=40 ? {z:"b",y:"c",why:"welded I-section, t<sub>f</sub> ≤ 40 mm"} : {z:"c",y:"d",why:"welded I-section, t<sub>f</sub> > 40 mm"};
  const hb=sp.D/sp.B;
  if(hb>1.2) return sp.tf<=40 ? {z:"a",y:"b",why:`rolled I-section, h/b<sub>f</sub> = ${f(hb,2)} > 1.2, t<sub>f</sub> ≤ 40 mm`} : {z:"b",y:"c",why:`rolled I-section, h/b<sub>f</sub> > 1.2, t<sub>f</sub> > 40 mm`};
  return sp.tf<=100 ? {z:"b",y:"c",why:`rolled I-section, h/b<sub>f</sub> = ${f(hb,2)} ≤ 1.2, t<sub>f</sub> ≤ 100 mm`} : {z:"d",y:"d",why:"rolled I-section, t<sub>f</sub> > 100 mm"};
}
function fcdOf(fy, KLr, cls){
  const a=ALPHA[cls], fcc=Math.PI**2*E_S/(KLr*KLr), ln=Math.sqrt(fy/fcc), ph=0.5*(1+a*(ln-0.2)+ln*ln);
  const chi=Math.min(1,1/(ph+Math.sqrt(Math.max(ph*ph-ln*ln,0))));
  return {fcc, ln, ph, chi, fcd:chi*fy/GM0, a};
}
const psiOf = (a,b) => { const A=Math.abs(a), B=Math.abs(b); if(Math.max(A,B)<1e-9) return 1; return A>=B ? b/a : a/b; };
const kOf = (cond, K) => COND[cond] && COND[cond][1]!==null ? COND[cond][1] : K;

function geomProblems(v){
  const p=[];
  if(!(v.L>0)) p.push("the column length must be positive");
  if(!(v.Ly>0)) p.push("the unbraced length about y-y must be positive");
  if(v.Ly>v.L+1e-9) p.push("the unbraced length about y-y cannot exceed the column length");
  if(!(v.LLT>0)) p.push("the effective length for lateral-torsional buckling must be positive");
  if(!(kOf(v.condZ,v.Kz)>0) || !(kOf(v.condY,v.Ky)>0)) p.push("the effective length factors must be positive");
  (v.combos||[]).forEach((c,i)=>{
    const n=`combination ${i+1}`;
    if(["P","Mzt","Mzb","Myt","Myb"].some(k=>!isFinite(c[k]))) p.push(`${n} has a missing value`);
    else if(!(c.P>0)) p.push(`${n}: the axial force must be compressive (positive)`);
  });
  if(!(v.combos||[]).length) p.push("add at least one load combination");
  if(v.fam==="BUILT"){
    if(!(v.gap>=0)) p.push("the gap between the components cannot be negative");
    ["nBays","bdE","bdI","bt","ov","wS"].forEach(k=>{ if(!(v[k]>0)) p.push("the batten details must all be positive"); });
    if(v.nBays%1) p.push("the number of bays must be a whole number");
  }
  return [...new Set(p)];
}

// ---------- design ----------
function design(v, SEC){
  const steps=[], checks=[]; let part="";
  const P_ = n => { part=n; };
  const Sx = (title, ref, lines, note) => steps.push({part,title,ref,lines:lines.filter(Boolean),note});
  const C = (group,name,ref,demand,capacity,ok,info) => checks.push({group,name,ref,demand,capacity,ok,info});
  const sp=secProps(v,SEC), G=GRADES[v.grade];
  const probs=geomProblems(v), inRows=inputRows(v,sp);
  if(!sp || probs.length) return {v,sp,steps,checks,early:true,probs:probs.length?probs:["the section is not defined"],inRows,allOk:false,failed:[],sumRows:[],outcomeRow:["Outcome","FAIL","Fix the inputs","FAIL"],actions:[],combos:[]};
  const kind=sp.kind, BU=kind==="BU", cs=BU?sp.comp:sp;

  // ===== A =====
  P_("A. Section, material and classification");
  const dimLine = kind==="O" ? `D = ${f(sp.D,1)} mm, t = ${f(sp.t,1)} mm` : kind==="R" ? `D = ${f(sp.D,1)} mm, B = ${f(sp.B,1)} mm, t = ${f(sp.t,1)} mm`
    : `D = ${f(cs.D,1)} mm, b<sub>f</sub> = ${f(cs.B,1)} mm, t<sub>w</sub> = ${f(cs.tw,1)} mm, t<sub>f</sub> = ${f(cs.tf,1)} mm${cs.R1?`, R<sub>1</sub> = ${f(cs.R1,1)} mm`:""}`;
  if(BU){
    const c=sp.comp, arrT=sp.arr==="side"?"side by side with the webs parallel":sp.arr==="toe"?"with the flange toes facing each other":"back to back (webs facing each other)";
    Sx("Built-up section", "Parallel axis theorem",
      [`Two ${c.name} (${c.famT}) placed ${arrT}, clear gap g = ${f(sp.gap,0)} mm, overall width W = g + 2b<sub>f</sub> = <span class="r">${f(sp.W,0)} mm</span>`,
       `One component: ${dimLine}; A = ${f(c.A,0)} mm², I<sub>z</sub> = ${f(c.Iz/1e4,1)} cm⁴, I<sub>y</sub> = ${f(c.Iy/1e4,1)} cm⁴, r<sub>min</sub> = r<sub>y</sub> = ${f(Math.sqrt(c.Iy/c.A),1)} mm${c.kind==="C"?`, centroid c<sub>y</sub> = ${f(c.cy,1)} mm from the back of the web`:""}`,
       `Distance from the built-up centroid to each component centroid, e = <span class="r">${f(sp.e,1)} mm</span>; centroid spacing 2e = ${f(2*sp.e,1)} mm`,
       `z-z (material axis, through both components): I<sub>z</sub> = 2 × ${f(c.Iz/1e4,1)} = <span class="r">${f(sp.Iz/1e4,1)} cm⁴</span>, r<sub>z</sub> = ${f(sp.rz,1)} mm`,
       `y-y (free axis, between the components): I<sub>y</sub> = 2(I<sub>y1</sub> + A<sub>1</sub>e²) = 2(${f(c.Iy/1e4,1)} + ${f(c.A/100,2)} × ${f(sp.e/10,2)}²) = <span class="r">${f(sp.Iy/1e4,1)} cm⁴</span>, r<sub>y</sub> = ${f(sp.ry,1)} mm`,
       `A = ${f(sp.A,0)} mm², mass ${f(sp.mass,2)} kg/m (battens extra); Z<sub>e,z</sub> = ${f(sp.Zez/1e3,1)} cm³, Z<sub>p,z</sub> = ${f(sp.Zpz/1e3,1)} cm³, Z<sub>e,y</sub> = I<sub>y</sub>/(W/2) = ${f(sp.Zey/1e3,1)} cm³, Z<sub>p,y</sub> = 2A<sub>1</sub>e = ${f(sp.Zpy/1e3,1)} cm³`],
      c.kind==="C" ? "The channel centroid is found from an idealized shape with parallel flanges of mean thickness. It is within a few millimetres of the tabulated value." : "");
  } else {
    Sx("Section properties", sp.src,
      [`${sp.name} (${sp.famT}); mass ${f(sp.mass,2)} kg/m; A = ${f(sp.A,0)} mm²`, dimLine,
       `I<sub>z</sub> = ${f(sp.Iz/1e4,1)} cm⁴, I<sub>y</sub> = ${f(sp.Iy/1e4,1)} cm⁴, r<sub>z</sub> = ${f(sp.rz,1)} mm, r<sub>y</sub> = ${f(sp.ry,1)} mm`,
       `Z<sub>e,z</sub> = ${f(sp.Zez/1e3,1)} cm³, Z<sub>p,z</sub> = ${f(sp.Zpz/1e3,1)} cm³, Z<sub>e,y</sub> = ${f(sp.Zey/1e3,1)} cm³, Z<sub>p,y</sub> = ${f(sp.Zpy/1e3,1)} cm³${sp.zpyCalc?" (y-y moduli computed from the plate idealization)":""}`,
       kind==="O"?"":`I<sub>t</sub> = ${f(sp.It/1e4,2)} cm⁴, I<sub>w</sub> = ${f(sp.Iw/1e6,0)} cm⁶${sp.itCalc||sp.iwCalc?" (computed where marked in the table)":""}`]);
  }
  const tmax=Math.max(cs.tf,cs.tw), fy=fyOf(G,tmax), fu=G.fu, eps=Math.sqrt(250/fy);
  Sx("Material", "IS 2062:2011 Table 2, IS 800 2.2.4, Table 5",
    [`Grade ${G.n}; thickest element ${f(tmax,1)} mm, so f<sub>y</sub> = <span class="r">${fy} MPa</span>, f<sub>u</sub> = ${fu} MPa`,
     `E = 2.0 × 10⁵ MPa, G = 0.769 × 10⁵ MPa, γ<sub>m0</sub> = 1.10`, `ε = √(250/f<sub>y</sub>) = <span class="r">${f3(eps)}</span>`]);

  // ===== B: actions =====
  P_("B. Design actions");
  const Psw = v.sw==="yes" ? v.gSW*sp.mass*9.81*v.L/1000 : 0;
  Sx("Load combinations", "5.3, Table 4",
    [`${v.combos.length} factored combination${v.combos.length>1?"s":""} entered; compression positive. End moments with the same sign bend the column in single curvature.`,
     v.sw==="yes" ? `Self weight of the column: ${f(v.gSW,2)} × ${f(sp.mass,2)} kg/m × 9.81 × ${f(v.L,3)} m/1000 = <span class="r">${f(Psw,2)} kN</span>, added to every combination (value at the base)` : "Self weight of the column not included",
     v.sway==="yes" ? "Frame is free to sway: C<sub>my</sub> = C<sub>mz</sub> = 0.9 (Table 18)" : "Frame is braced against sway: C<sub>m</sub> = 0.6 + 0.4ψ ≥ 0.4 from the end moment ratio ψ (Table 18)"]);

  // ===== C: slenderness and axial strength =====
  P_("C. Slenderness and compressive strength");
  const Kz=kOf(v.condZ,v.Kz), Ky=kOf(v.condY,v.Ky), Lez=Kz*v.L*1000, Ley=Ky*v.Ly*1000;
  const lz0=Lez/sp.rz, ly0=Ley/sp.ry, bf_=BU?1.1:1, lz=bf_*lz0, ly=bf_*ly0;
  Sx("Effective lengths and slenderness", "7.2.2, Table 11" + (BU?", 7.7.1.4":""),
    [`z-z: ${COND[v.condZ][0].toLowerCase()}, K = ${f(Kz,2)}; KL = ${f(Kz,2)} × ${f(v.L,3)} = ${f(Lez/1000,3)} m; KL/r<sub>z</sub> = ${f(Lez,0)}/${f(sp.rz,1)} = <span class="r">${f(lz0,1)}</span>`,
     `y-y: ${COND[v.condY][0].toLowerCase()}, K = ${f(Ky,2)}; unbraced length ${f(v.Ly,3)} m; KL = ${f(Ley/1000,3)} m; KL/r<sub>y</sub> = ${f(Ley,0)}/${f(sp.ry,1)} = <span class="r">${f(ly0,1)}</span>`,
     BU ? `Battened column: effective slenderness = 1.1 × actual, to allow for shear deformation: z-z <span class="r">${f(lz,1)}</span>, y-y <span class="r">${f(ly,1)}</span>; the larger, ${f(Math.max(lz,ly),1)}, governs` : ""]);
  const lmax=Math.max(lz,ly);
  C("Slenderness and axial strength",`Slenderness, KL/r ≤ ${v.slim}`,"3.8, Table 3",`≤ ${v.slim}`,f(lmax,1), lmax<=v.slim);
  const bc=buckClass(sp,v.hollow), FZ=fcdOf(fy,lz,bc.z), FY=fcdOf(fy,ly,bc.y);
  const Pdz=sp.A*FZ.fcd/1e3, Pdy=sp.A*FY.fcd/1e3, Pd=Math.min(Pdz,Pdy);
  const fl = (F,ax,lam) => `${ax}: buckling class ${ax==="z-z"?bc.z:bc.y}, α = ${F.a}; f<sub>cc</sub> = π²E/(KL/r)² = ${f(F.fcc,1)} MPa; λ = √(f<sub>y</sub>/f<sub>cc</sub>) = ${f3(F.ln)}; φ = ${f3(F.ph)}; χ = ${f3(F.chi)}; f<sub>cd</sub> = <span class="r">${f(F.fcd,1)} MPa</span>`;
  Sx("Design compressive strength", "7.1.2, 7.1.2.1, Table 10",
    [`Buckling class from Table 10 for a ${bc.why}: z-z class ${bc.z}, y-y class ${bc.y}`, fl(FZ,"z-z",lz), fl(FY,"y-y",ly),
     `φ = 0.5[1 + α(λ − 0.2) + λ²], f<sub>cd</sub> = (f<sub>y</sub>/γ<sub>m0</sub>)/[φ + √(φ² − λ²)] ≤ f<sub>y</sub>/γ<sub>m0</sub>`,
     `P<sub>dz</sub> = A f<sub>cd,z</sub> = ${f(sp.A,0)} × ${f(FZ.fcd,1)}/10³ = <span class="r">${f(Pdz,1)} kN</span>; P<sub>dy</sub> = ${f(sp.A,0)} × ${f(FY.fcd,1)}/10³ = <span class="r">${f(Pdy,1)} kN</span>`,
     `P<sub>d</sub> = <span class="r">${f(Pd,1)} kN</span> (gross area; the section is checked for slenderness in each combination)`],
    kind==="C" ? "A single channel is checked for flexural buckling only. Torsional and flexural-torsional buckling of an unsymmetric section is not covered." : "");

  // ===== per combination =====
  const sway=v.sway==="yes";
  const ltbSusceptible = (kind==="I"||kind==="C"||(kind==="R"&&sp.Iy<sp.Iz*0.999)||(BU&&sp.Iy<sp.Iz*0.999));
  let Avz, Avy, avzT, avyT; // Avz: area for shear from Mz (along y, parallel to web); Avy: shear from My
  if(kind==="O"){ Avz=Avy=2*sp.A/Math.PI; avzT=avyT=`A<sub>v</sub> = 2A/π = ${f(Avz,0)} mm²`; }
  else if(kind==="R"){ Avz=sp.A*sp.D/(sp.B+sp.D); Avy=sp.A*sp.B/(sp.B+sp.D); avzT=`A<sub>v</sub> = AD/(B + D) = ${f(Avz,0)} mm²`; avyT=`A<sub>v</sub> = AB/(B + D) = ${f(Avy,0)} mm²`; }
  else { const n=BU?2:1; Avz=n*(sp.welded?(sp.D-2*sp.tf):cs.D)*cs.tw; Avy=n*2*cs.B*cs.tf; avzT=`A<sub>v</sub> = ${n>1?"2 × ":""}${sp.welded?"d":"D"}t<sub>w</sub> = ${f(Avz,0)} mm²`; avyT=`A<sub>v</sub> = ${n>1?"2 × ":""}2b<sub>f</sub>t<sub>f</sub> = ${f(Avy,0)} mm²`; }
  const Vdz=Avz*fy/Math.sqrt(3)/GM0/1e3, Vdy=Avy*fy/Math.sqrt(3)/GM0/1e3;
  const Nd=sp.A*fy/GM0/1e3;
  const combos=v.combos.map((c0,i)=>{
    const c={...c0, i, P:c0.P+Psw, Pin:c0.P};
    c.Mz=Math.max(Math.abs(c.Mzt),Math.abs(c.Mzb)); c.My=Math.max(Math.abs(c.Myt),Math.abs(c.Myb));
    c.hasM=c.Mz>1e-9||c.My>1e-9;
    c.cl=classify(sp,fy,c.P,c.hasM);
    const cl=c.cl.c, bz = cl<=1?1:sp.Zez/sp.Zpz, by = cl<=1?1:sp.Zey/sp.Zpy;
    c.bz=bz; c.by=by;
    c.Mdz=Math.min(bz*sp.Zpz, 1.2*sp.Zez)*fy/GM0/1e6; c.Mdy=Math.min(by*sp.Zpy, 1.2*sp.Zey)*fy/GM0/1e6;
    c.psiZ=psiOf(c.Mzt,c.Mzb); c.psiY=psiOf(c.Myt,c.Myb);
    c.Cmz = sway?0.9:Math.max(0.4,0.6+0.4*c.psiZ); c.Cmy = sway?0.9:Math.max(0.4,0.6+0.4*c.psiY); c.CmLT=Math.max(0.4,0.6+0.4*c.psiZ);
    // LTB
    c.ltb = ltbSusceptible && c.Mz>1e-9;
    c.MdzLT=c.Mdz; c.lamLT=0;
    if(c.ltb){
      c.C1=c1Of(c.psiZ); const Lm=v.LLT*1000, a=Math.PI**2*E_S*sp.Iy/(Lm*Lm);
      c.Mcr=c.C1*Math.sqrt(a*(G_S*sp.It+Math.PI**2*E_S*sp.Iw/(Lm*Lm)));
      c.lamLT=Math.sqrt(bz*sp.Zpz*fy/c.Mcr); c.aLT=sp.welded?0.49:0.21;
      const ph=0.5*(1+c.aLT*(c.lamLT-0.2)+c.lamLT**2); c.phLT=ph; c.chiLT=Math.min(1,1/(ph+Math.sqrt(ph*ph-c.lamLT**2)));
      c.MdL=bz*sp.Zpz*c.chiLT*fy/GM0/1e6;
      c.MdzLT = c.lamLT<=0.4 ? c.Mdz : Math.min(c.Mdz,c.MdL);
    }
    // shear from end moments
    c.Vz=Math.abs(c.Mzt-c.Mzb)/v.L; c.Vy=Math.abs(c.Myt-c.Myb)/v.L;
    c.hsZ=c.Vz>0.6*Vdz; c.hsY=c.Vy>0.6*Vdy;
    const Mdzs = c.hsZ ? sp.Zez*fy/GM0/1e6 : c.Mdz, Mdys = c.hsY ? sp.Zey*fy/GM0/1e6 : c.Mdy;
    c.Mdzs=Mdzs; c.Mdys=Mdys;
    // section strength 9.3.1
    const n=c.P/Nd; c.nr=n;
    if(cl<=1 && !c.hsZ && !c.hsY && (kind==="I"||kind==="R"||kind==="O")){
      c.secM="9.3.1.1";
      if(kind==="O"){ c.Mndz=Math.min(c.Mdz,1.04*c.Mdz*(1-Math.pow(n,1.7))); c.Mndy=Math.min(c.Mdy,1.04*c.Mdy*(1-Math.pow(n,1.7))); c.a1=c.a2=2; c.mndT="M<sub>nd</sub> = 1.04M<sub>d</sub>(1 − n<sup>1.7</sup>) ≤ M<sub>d</sub>; α<sub>1</sub> = α<sub>2</sub> = 2"; }
      else if(kind==="R"){ const aw=Math.min((sp.A-2*sp.B*sp.t)/sp.A,0.5), af=Math.min((sp.A-2*sp.D*sp.t)/sp.A,0.5); c.Mndz=Math.min(c.Mdz,c.Mdz*(1-n)/(1-0.5*aw)); c.Mndy=Math.min(c.Mdy,c.Mdy*(1-n)/(1-0.5*af)); c.a1=c.a2=Math.min(6,1.66/(1-1.13*n*n)); c.mndT=`a<sub>w</sub> = ${f3(aw)}, a<sub>f</sub> = ${f3(af)}; M<sub>ndz</sub> = M<sub>dz</sub>(1 − n)/(1 − 0.5a<sub>w</sub>), M<sub>ndy</sub> = M<sub>dy</sub>(1 − n)/(1 − 0.5a<sub>f</sub>); α = 1.66/(1 − 1.13n²) = ${f3(c.a1)}`; }
      else if(sp.welded){ const a=Math.min((sp.A-2*sp.B*sp.tf)/sp.A,0.5); c.Mndz=Math.min(c.Mdz,c.Mdz*(1-n)/(1-0.5*a)); c.Mndy = n<=a ? c.Mdy : c.Mdy*(1-((n-a)/(1-a))**2); c.a1=Math.max(1,5*n); c.a2=2; c.mndT=`a = (A − 2bt<sub>f</sub>)/A = ${f3(a)}; M<sub>ndz</sub> = M<sub>dz</sub>(1 − n)/(1 − 0.5a) ≤ M<sub>dz</sub>; M<sub>ndy</sub> = ${n<=a?"M<sub>dy</sub> (n ≤ a)":"M<sub>dy</sub>[1 − ((n − a)/(1 − a))²]"}; α<sub>1</sub> = 5n ≥ 1, α<sub>2</sub> = 2`; }
      else { c.Mndz=Math.min(c.Mdz,1.11*c.Mdz*(1-n)); c.Mndy = n<=0.2 ? c.Mdy : Math.min(c.Mdy,1.56*c.Mdy*(1-n)*(n+0.6)); c.a1=Math.max(1,5*n); c.a2=2; c.mndT=`Rolled I: M<sub>ndz</sub> = 1.11M<sub>dz</sub>(1 − n) ≤ M<sub>dz</sub>; M<sub>ndy</sub> = ${n<=0.2?"M<sub>dy</sub> (n ≤ 0.2)":"1.56M<sub>dy</sub>(1 − n)(n + 0.6)"}; α<sub>1</sub> = 5n ≥ 1, α<sub>2</sub> = 2`; }
      c.Usec = n>=1 ? n : Math.pow(c.My/Math.max(c.Mndy,1e-9),c.a1)+Math.pow(c.Mz/Math.max(c.Mndz,1e-9),c.a2);
    } else {
      c.secM="9.3.1.3";
      c.Usec = n + c.Mz/Mdzs + c.My/Mdys;
    }
    // member buckling 9.3.2.2
    c.ny=c.P/Pdy; c.nz=c.P/Pdz;
    c.Ky=Math.min(1+(FY.ln-0.2)*c.ny, 1+0.8*c.ny); c.Kz=Math.min(1+(FZ.ln-0.2)*c.nz, 1+0.8*c.nz);
    c.KLT = c.ltb ? Math.max(1-0.1*c.lamLT*c.ny/(c.CmLT-0.25), 1-0.1*c.ny/(c.CmLT-0.25)) : 1;
    c.eq1 = c.ny + c.Ky*c.Cmy*c.My/c.Mdy + c.KLT*c.Mz/c.MdzLT;
    c.eq2 = c.nz + 0.6*c.Ky*c.Cmy*c.My/c.Mdy + c.Kz*c.Cmz*c.Mz/c.MdzLT;
    c.uAx=c.P/Pd; c.uSh=Math.max(c.Vz/Vdz, c.Vy/Vdy);
    c.u=Math.max(c.uAx, c.Usec, c.eq1, c.eq2, c.uSh);
    return c;
  });
  const gv = combos.reduce((a,b)=>b.u>a.u?b:a);
  const cname = c => `Combination ${c.i+1}${c.n?` (${c.n})`:""}`;

  P_("B. Design actions");
  Sx("Factored actions in each combination", "Statics",
    combos.map(c=>`${cname(c)}: P = ${f(c.Pin,1)}${Psw?` + ${f(Psw,1)}`:""} = <span class="r">${f(c.P,1)} kN</span>; M<sub>z</sub> top/bottom = ${sg(c.Mzt,1)}/${sg(c.Mzb,1)} kN·m (ψ<sub>z</sub> = ${f(c.psiZ,2)}); M<sub>y</sub> top/bottom = ${sg(c.Myt,1)}/${sg(c.Myb,1)} kN·m (ψ<sub>y</sub> = ${f(c.psiY,2)}); end shears V = |M<sub>top</sub> − M<sub>bot</sub>|/L: ${f(c.Vz,1)} kN (from M<sub>z</sub>), ${f(c.Vy,1)} kN (from M<sub>y</sub>)`),
    "With no load along the height, the largest moment about each axis is at one end and the shear is constant.");
  // move "B" steps next to their part: re-sort steps by part letter
  P_("A. Section, material and classification");
  Sx("Section classification", "3.7.2, Table 2",
    [...gv.cl.lines.map(l=>`${cname(gv)} (governing): ${l}`), `Section class for the governing combination = <span class="r">${CLS[gv.cl.c]}</span>${gv.hasM?`; β<sub>b,z</sub> = ${f3(gv.bz)}, β<sub>b,y</sub> = ${f3(gv.by)}`:" (axial compression only)"}`,
     ...combos.filter(c=>c!==gv).map(c=>`${cname(c)}: ${CLS[c.cl.c]}`)],
    combos.some(c=>c.cl.c===3) ? "A slender section needs the effective area of 7.3.2 and is not covered by this sheet. Choose a section with thicker plates." : "");
  combos.forEach(c=>C("Section and material",`${cname(c)}: section is not slender`,"Table 2",`Plastic, compact or semi-compact`,CLS[c.cl.c], c.cl.c<3));

  P_("C. Slenderness and compressive strength");
  combos.forEach(c=>C("Slenderness and axial strength",`${cname(c)}: axial compression`,"7.1.2",`P = ${f(c.P,1)} kN`,`P<sub>d</sub> = ${f(Pd,1)} kN`, c.P<=Pd));

  // ===== D: bending =====
  P_("D. Bending strength");
  const g=gv;
  if(combos.some(c=>c.hasM)){
    const cm = g.hasM ? g : combos.find(c=>c.hasM);
    Sx("Design bending strength of the section", "8.2.1.2",
      [`${cname(cm)}: M<sub>dz</sub> = β<sub>b</sub>Z<sub>p,z</sub>f<sub>y</sub>/γ<sub>m0</sub> ≤ 1.2Z<sub>e,z</sub>f<sub>y</sub>/γ<sub>m0</sub> = min(${f3(cm.bz)} × ${f(sp.Zpz/1e3,1)}, 1.2 × ${f(sp.Zez/1e3,1)}) × 10³ × ${fy}/1.10/10⁶ = <span class="r">${f(cm.Mdz,2)} kN·m</span>`,
       `M<sub>dy</sub> = min(${f3(cm.by)} × ${f(sp.Zpy/1e3,1)}, 1.2 × ${f(sp.Zey/1e3,1)}) × 10³ × ${fy}/1.10/10⁶ = <span class="r">${f(cm.Mdy,2)} kN·m</span>`]);
    if(cm.ltb){
      Sx("Lateral-torsional buckling about z-z", "8.2.2, Annex E",
        [`Effective length L<sub>LT</sub> = ${f(v.LLT,3)} m; ψ<sub>z</sub> = ${f(cm.psiZ,2)}, so C<sub>1</sub> = ${f3(cm.C1)} (Table 42, K = 1, end moments)`,
         `M<sub>cr</sub> = C<sub>1</sub>√{(π²EI<sub>y</sub>/L<sub>LT</sub>²)[GI<sub>t</sub> + π²EI<sub>w</sub>/L<sub>LT</sub>²]} = <span class="r">${f(cm.Mcr/1e6,2)} kN·m</span>`,
         `λ<sub>LT</sub> = √(β<sub>b</sub>Z<sub>p</sub>f<sub>y</sub>/M<sub>cr</sub>) = <span class="r">${f3(cm.lamLT)}</span>; α<sub>LT</sub> = ${cm.aLT}; φ<sub>LT</sub> = ${f3(cm.phLT)}; χ<sub>LT</sub> = ${f3(cm.chiLT)}`,
         cm.lamLT<=0.4 ? `λ<sub>LT</sub> ≤ 0.4, so no reduction: M<sub>dz</sub> = ${f(cm.Mdz,2)} kN·m` : `M<sub>dz</sub> = β<sub>b</sub>Z<sub>p</sub>χ<sub>LT</sub>f<sub>y</sub>/γ<sub>m0</sub> = <span class="r">${f(cm.MdzLT,2)} kN·m</span>`],
        (BU?"For the built-up section, I<sub>t</sub> is the sum for the two components and I<sub>w</sub> is approximated as I<sub>y</sub>h²/4. ":"") + (kind==="C"?"For a channel the formula assumes the load acts through the shear centre.":""));
    } else Sx("Lateral-torsional buckling about z-z", "8.2.2",
      [kind==="O"?"Circular hollow sections do not buckle laterally.": (kind==="R"||BU) ? `I<sub>y</sub> ≥ I<sub>z</sub>, so bending about z-z is bending about the weaker axis and lateral-torsional buckling does not occur.` : "No moment about z-z, so lateral-torsional buckling does not arise."]);
  } else Sx("Bending", "–", ["No end moments in any combination; the column carries axial force only"]);

  // ===== E: shear =====
  P_("E. Shear");
  Sx("Shear from the end moments", "8.4.1",
    [`Shear along the web (from M<sub>z</sub>): ${avzT}; V<sub>d</sub> = A<sub>v</sub>f<sub>y</sub>/(√3γ<sub>m0</sub>) = <span class="r">${f(Vdz,1)} kN</span>`,
     `Shear across the flanges (from M<sub>y</sub>): ${avyT}; V<sub>d</sub> = <span class="r">${f(Vdy,1)} kN</span>`,
     `Largest: V<sub>z</sub> = ${f(Math.max(...combos.map(c=>c.Vz)),1)} kN, V<sub>y</sub> = ${f(Math.max(...combos.map(c=>c.Vy)),1)} kN`,
     combos.some(c=>c.hsZ||c.hsY) ? "High shear (V > 0.6V<sub>d</sub>) in some combinations: the section check there uses the elastic moment capacity Z<sub>e</sub>f<sub>y</sub>/γ<sub>m0</sub> (9.2.2, conservative)." : "V ≤ 0.6V<sub>d</sub> throughout, so the moment capacity is not reduced (9.2.2)"]);
  if(combos.some(c=>c.Vz>0||c.Vy>0)) combos.filter(c=>c.Vz>0||c.Vy>0).forEach(c=>C("Shear",`${cname(c)}: shear`,"8.4.1",`V = ${f(Math.max(c.Vz,c.Vy),1)} kN`,`V<sub>d</sub> = ${f(c.Vz/Vdz>=c.Vy/Vdy?Vdz:Vdy,1)} kN`, c.uSh<=1));

  // ===== F: combined =====
  P_("F. Axial force with bending");
  combos.forEach(c=>{
    const lines=[`P = ${f(c.P,1)} kN, M<sub>z</sub> = ${f(c.Mz,2)} kN·m, M<sub>y</sub> = ${f(c.My,2)} kN·m; class ${CLS[c.cl.c]}`,
      `n = P/N<sub>d</sub>, N<sub>d</sub> = Af<sub>y</sub>/γ<sub>m0</sub> = ${f(Nd,1)} kN; n = <span class="r">${f3(c.nr)}</span>`];
    if(c.secM==="9.3.1.1") lines.push(c.mndT, `M<sub>ndz</sub> = ${f(c.Mndz,2)} kN·m, M<sub>ndy</sub> = ${f(c.Mndy,2)} kN·m`, `(M<sub>y</sub>/M<sub>ndy</sub>)<sup>α1</sup> + (M<sub>z</sub>/M<sub>ndz</sub>)<sup>α2</sup> = (${f3(c.My/c.Mndy)})<sup>${f(c.a1,2)}</sup> + (${f3(c.Mz/c.Mndz)})<sup>${f(c.a2,2)}</sup> = <span class="r">${f3(c.Usec)}</span> ≤ 1`);
    else lines.push(`N/N<sub>d</sub> + M<sub>z</sub>/M<sub>dz</sub> + M<sub>y</sub>/M<sub>dy</sub> = ${f3(c.nr)} + ${f(c.Mz,2)}/${f(c.Mdzs,2)} + ${f(c.My,2)}/${f(c.Mdys,2)} = <span class="r">${f3(c.Usec)}</span> ≤ 1`);
    lines.push(`Member buckling: n<sub>y</sub> = P/P<sub>dy</sub> = ${f3(c.ny)}, n<sub>z</sub> = P/P<sub>dz</sub> = ${f3(c.nz)}; K<sub>y</sub> = 1 + (λ<sub>y</sub> − 0.2)n<sub>y</sub> ≤ 1 + 0.8n<sub>y</sub> = ${f3(c.Ky)}; K<sub>z</sub> = ${f3(c.Kz)}; C<sub>my</sub> = ${f3(c.Cmy)}, C<sub>mz</sub> = ${f3(c.Cmz)}${c.ltb?`, C<sub>mLT</sub> = ${f3(c.CmLT)}; K<sub>LT</sub> = 1 − 0.1λ<sub>LT</sub>n<sub>y</sub>/(C<sub>mLT</sub> − 0.25) = ${f3(c.KLT)}`:`; K<sub>LT</sub> = 1 (no lateral-torsional buckling)`}`,
      `P/P<sub>dy</sub> + K<sub>y</sub>C<sub>my</sub>M<sub>y</sub>/M<sub>dy</sub> + K<sub>LT</sub>M<sub>z</sub>/M<sub>dz</sub> = ${f3(c.ny)} + ${f3(c.Ky*c.Cmy*c.My/c.Mdy)} + ${f3(c.KLT*c.Mz/c.MdzLT)} = <span class="r">${f3(c.eq1)}</span>`,
      `P/P<sub>dz</sub> + 0.6K<sub>y</sub>C<sub>my</sub>M<sub>y</sub>/M<sub>dy</sub> + K<sub>z</sub>C<sub>mz</sub>M<sub>z</sub>/M<sub>dz</sub> = ${f3(c.nz)} + ${f3(0.6*c.Ky*c.Cmy*c.My/c.Mdy)} + ${f3(c.Kz*c.Cmz*c.Mz/c.MdzLT)} = <span class="r">${f3(c.eq2)}</span>`,
      c.ltb ? `M<sub>dz</sub> here includes lateral-torsional buckling: ${f(c.MdzLT,2)} kN·m` : "");
    Sx(`${cname(c)}${c===gv?", governing":""}`, `9.3.1, 9.3.2.2${c.secM==="9.3.1.1"?", Table 17":""}`, lines,
      c.secM==="9.3.1.3" && c.hasM && c.cl.c<=1 ? (kind==="C"||BU ? "No reduced moment formula is given for channels or built-up sections, so the linear interaction of 9.3.1.3 is used." : "High shear: the linear interaction with elastic moment capacities is used.") : "");
    if(c.hasM){
      C("Axial force with bending",`${cname(c)}: section strength`,c.secM,"≤ 1.0",f3(c.Usec), c.Usec<=1);
      C("Axial force with bending",`${cname(c)}: member buckling, minor axis equation`,"9.3.2.2","≤ 1.0",f3(c.eq1), c.eq1<=1);
      C("Axial force with bending",`${cname(c)}: member buckling, major axis equation`,"9.3.2.2","≤ 1.0",f3(c.eq2), c.eq2<=1);
    }
  });

  // ===== G: battens =====
  let bat=null;
  if(BU){
    P_("G. Battens");
    const c=sp.comp, rc=Math.sqrt(c.Iy/c.A), Cs=v.L*1000/v.nBays, N=2, dc=2*sp.e, W=sp.W, ov=Math.min(v.ov,c.B);
    bat={Cs, dc, W, ov, rc};
    Sx("Layout", "7.7.1.1, 7.7.1.3",
      [`${v.nBays} equal bays over L = ${f(v.L,3)} m, so the battens are at C = <span class="r">${f(Cs,0)} mm</span> centre to centre, on both faces (N = 2 planes)`,
       `Batten plates ${f(v.bt,0)} mm thick, ${f(W,0)} mm long; end battens ${f(v.bdE,0)} mm deep, intermediate battens ${f(v.bdI,0)} mm deep; lap on each component ${f(ov,0)} mm`,
       `r<sub>y</sub> (about the axis perpendicular to the battens) = ${f(sp.ry,1)} mm; r<sub>z</sub> (about the axis parallel to them) = ${f(sp.rz,1)} mm`]);
    C("Battens","Number of bays ≥ 3","7.7.1.3","≥ 3",String(v.nBays), v.nBays>=3);
    C("Battens","r<sub>y</sub> ≥ r<sub>z</sub> (preferred where practicable)","7.7.1.1",`≥ ${f(sp.rz,1)} mm`,`${f(sp.ry,1)} mm`, sp.ry>=sp.rz-1e-9, sp.ry<sp.rz-1e-9);
    if(combos.some(c=>c.My>1e-9)) C("Battens","Moment in the plane of the battens","7.7.1.2","Exact stability analysis or tests","M<sub>y</sub> present", false, true);
    const lc=Cs/rc, lcl=Math.min(50,0.7*lz0);
    Sx("Spacing of battens", "7.7.3",
      [`Slenderness of one component between battens = C/r<sub>min</sub> = ${f(Cs,0)}/${f(rc,1)} = <span class="r">${f(lc,1)}</span>`,
       `Limit: not more than 50, nor more than 0.7 × slenderness of the whole member about z-z (axis parallel to the battens) = 0.7 × ${f(lz0,1)} = ${f(0.7*lz0,1)}; limit = <span class="r">${f(lcl,1)}</span>`]);
    C("Battens","Component slenderness between battens","7.7.3",`≤ ${f(lcl,1)}`,f(lc,1), lc<=lcl);
    // forces
    const Vt=Math.max(...combos.map(c=>0.025*c.P+c.Vy)), gvt=combos.reduce((a,b)=>0.025*b.P+b.Vy>0.025*a.P+a.Vy?b:a);
    const fyb=fyOf(G,v.bt), fuw=Math.min(fu,410), fwd=fuw/(Math.sqrt(3)*GMW), inner=W-2*ov;
    const one = (d,lab) => {
      const xb=ov*ov/(2*ov+d), S=W-2*xb, Vb=Vt*Cs/(N*S), M=Vt*Cs/(2*N); // kN, kN·mm
      const tau=Vb*1e3/(v.bt*d), sig=6*M*1e3/(v.bt*d*d), taul=fyb/(Math.sqrt(3)*GM0), sigl=fyb/GM0;
      const Lw=d+2*ov, Ix=d**3/12+2*ov*(d/2)**2, Iyw=d*xb*xb+2*(ov**3/12+ov*(ov/2-xb)**2), Ip=Ix+Iyw, Mn=M*1e3, Vn=Vb*1e3;
      let q=0; [[-xb,d/2],[-xb,-d/2],[ov-xb,d/2],[ov-xb,-d/2]].forEach(([x,y])=>[1,-1].forEach(s=>{ const qx=-s*Mn*y/Ip, qy=s*Mn*x/Ip+Vn/Lw; q=Math.max(q,Math.hypot(qx,qy)); }));
      const fw=q/(0.7*v.wS);
      return {d,lab,xb,S,Vb,M,tau,sig,taul,sigl,Lw,Ip,q,fw};
    };
    const bE=one(v.bdE,"End batten"), bI=one(v.bdI,"Intermediate batten");
    Object.assign(bat,{Vt,bE,bI,fwd,fyb,inner});
    Sx("Design forces", "7.7.2.1",
      [`Transverse shear V<sub>t</sub> = 2.5% of the axial force + any actual shear across the battens (from M<sub>y</sub>): ${cname(gvt)}: 0.025 × ${f(gvt.P,1)} + ${f(gvt.Vy,1)} = <span class="r">${f(Vt,2)} kN</span>`,
       `Longitudinal shear per batten V<sub>b</sub> = V<sub>t</sub>C/(NS) and moment M = V<sub>t</sub>C/(2N), where S is the distance between the centroids of the weld groups`,
       ...[bE,bI].map(b=>`${b.lab} (d = ${f(b.d,0)} mm): weld group centroid ${f(b.xb,1)} mm in from the batten end, S = W − 2x̄ = ${f(b.S,1)} mm; V<sub>b</sub> = ${f(Vt,2)} × ${f(Cs,0)}/(2 × ${f(b.S,1)}) = <span class="r">${f(b.Vb,2)} kN</span>; M = ${f(Vt,2)} × ${f(Cs,0)}/4 = <span class="r">${f(b.M/1e3,3)} kN·m</span>`)]);
    Sx("Batten size", "7.7.2.3, 7.7.4.1",
      [`End battens: effective depth ≥ distance between component centroids 2e = ${f(dc,1)} mm, and ≥ 2b<sub>f</sub> = ${f(2*c.B,0)} mm; provided ${f(v.bdE,0)} mm`,
       `Intermediate battens: ≥ 0.75 × 2e = ${f(0.75*dc,1)} mm, and ≥ 2b<sub>f</sub> = ${f(2*c.B,0)} mm; provided ${f(v.bdI,0)} mm`,
       `Thickness ≥ 1/50 of the distance between the innermost weld lines = ${f(inner,0)}/50 = ${f(inner/50,1)} mm; provided ${f(v.bt,0)} mm`,
       `Lap on each component ≥ 4t = ${f(4*v.bt,0)} mm; provided ${f(ov,0)} mm (the weld returns along the top and bottom edges over this lap)`]);
    C("Battens","End batten depth","7.7.2.3",`≥ ${f(Math.max(dc,2*c.B),0)} mm`,`${f(v.bdE,0)} mm`, v.bdE>=Math.max(dc,2*c.B)-0.5);
    C("Battens","Intermediate batten depth","7.7.2.3",`≥ ${f(Math.max(0.75*dc,2*c.B),0)} mm`,`${f(v.bdI,0)} mm`, v.bdI>=Math.max(0.75*dc,2*c.B)-0.5);
    C("Battens","Batten thickness","7.7.2.3",`≥ ${f(inner/50,1)} mm`,`${f(v.bt,0)} mm`, v.bt>=inner/50-1e-9);
    C("Battens","Lap on each component","7.7.4.1",`≥ ${f(4*v.bt,0)} mm`,`${f(ov,0)} mm`, ov>=4*v.bt-1e-9);
    Sx("Batten plate stresses", "7.7.2.1, 8.4.1, 8.2.1",
      [`f<sub>y</sub> of the batten plate = ${fyb} MPa; shear limit f<sub>y</sub>/(√3γ<sub>m0</sub>) = ${f(bI.taul,1)} MPa; bending limit f<sub>y</sub>/γ<sub>m0</sub> = ${f(bI.sigl,1)} MPa`,
       ...[bE,bI].map(b=>`${b.lab}: τ = V<sub>b</sub>/(td) = ${f(b.Vb*1e3,0)}/(${f(v.bt,0)} × ${f(b.d,0)}) = <span class="r">${f(b.tau,1)} MPa</span>; σ = 6M/(td²) = <span class="r">${f(b.sig,1)} MPa</span>`)]);
    [bE,bI].forEach(b=>{
      C("Battens",`${b.lab}: shear stress`,"8.4.1",`≤ ${f(b.taul,1)} MPa`,`${f(b.tau,1)} MPa`, b.tau<=b.taul);
      C("Battens",`${b.lab}: bending stress`,"8.2.1",`≤ ${f(b.sigl,1)} MPa`,`${f(b.sig,1)} MPa`, b.sig<=b.sigl);
    });
    const tth=Math.max(v.bt,c.tf), smin=tth<=10?3:tth<=20?5:tth<=32?6:8, smax=v.bt-1.5;
    Sx("Welds connecting the battens", "10.5.7, 10.5.2.3, Table 21, 7.7.4.1",
      [`Fillet weld size s = ${f(v.wS,1)} mm, throat 0.7s = ${f(0.7*v.wS,2)} mm; weld along the batten end (length d) with returns of ${f(ov,0)} mm along the top and bottom edges`,
       `Minimum size for the thicker part (${f(tth,1)} mm) = ${smin} mm (Table 21); maximum on the square edge of the plate = t − 1.5 = ${f(smax,1)} mm`,
       `Weld design strength f<sub>wd</sub> = f<sub>u</sub>/(√3γ<sub>mw</sub>) = ${fuw}/(√3 × 1.25) = <span class="r">${f(fwd,1)} MPa</span> (shop weld, f<sub>u</sub> the lesser of the plate and the electrode, 410 MPa)`,
       ...[bE,bI].map(b=>`${b.lab}: weld length ${f(b.Lw,0)} mm, polar moment ${f(b.Ip/1e6,3)} × 10⁶ mm³ per mm of throat; worst corner resultant ${f(b.q,1)} N/mm from V<sub>b</sub>/L<sub>w</sub> plus Mr/I<sub>p</sub>; stress = ${f(b.q,1)}/${f(0.7*v.wS,2)} = <span class="r">${f(b.fw,1)} MPa</span>`)],
      "The weld on each vertical edge is the full batten depth, which meets the 7.7.4.1 rule of at least half the depth with a third at each end.");
    C("Battens","Fillet weld size","Table 21, 10.5.8",`${smin} to ${f(smax,1)} mm`,`${f(v.wS,1)} mm`, v.wS>=smin-1e-9 && v.wS<=smax+1e-9);
    [bE,bI].forEach(b=>C("Battens",`${b.lab}: weld stress`,"10.5.7.1.1",`≤ ${f(fwd,1)} MPa`,`${f(b.fw,1)} MPa`, b.fw<=fwd));
    bat.smin=smin; bat.smax=smax;
  }

  // order steps by part letter so the B steps sit together
  steps.sort((a,b)=>a.part.localeCompare(b.part));
  const GO=["Section and material","Slenderness and axial strength","Shear","Axial force with bending","Battens"];
  checks.sort((a,b)=>GO.indexOf(a.group)-GO.indexOf(b.group));

  const failed=checks.filter(k=>!k.ok && !k.info), allOk=!failed.length;
  const batU = bat ? Math.max(bat.bE.fw/bat.fwd, bat.bI.fw/bat.fwd, bat.bE.sig/bat.bE.sigl, bat.bI.sig/bat.bI.sigl, bat.bE.tau/bat.bE.taul, bat.bI.tau/bat.bI.taul, (bat.Cs/bat.rc)/Math.min(50,0.7*lz0)) : null;
  const uAx=Math.max(...combos.map(c=>c.uAx)), uSec=Math.max(...combos.map(c=>c.hasM?c.Usec:0)), uMem=Math.max(...combos.map(c=>c.hasM?Math.max(c.eq1,c.eq2):0));
  const utils=[["Axial",uAx],["Section",uSec],["Member buckling",uMem],[BU?"Battens":"Slenderness", BU?batU:lmax/v.slim]];
  const govU=utils.reduce((a,b)=>b[1]>a[1]?b:a);
  const st2 = ok => ok ? "PASS" : "FAIL";
  const sumRows=[
    {g:"Section"}, ["Section", sp.name, `${f(sp.mass,2)} kg/m, ${G.n}, f<sub>y</sub> = ${fy} MPa`, ""],
    ["Classification", combos.map(c=>CLS[c.cl.c]).filter((x,i,a)=>a.indexOf(x)===i).join(", "), "", st2(combos.every(c=>c.cl.c<3))],
    ["Slenderness", `KL/r = ${f(lmax,1)}`, `z-z ${f(lz,1)}, y-y ${f(ly,1)}${BU?" (× 1.1 for battens)":""}; limit ${v.slim}`, st2(lmax<=v.slim)],
    {g:"Strength"},
    ["Axial compression", `P = ${f(Math.max(...combos.map(c=>c.P)),1)} kN`, `P<sub>d</sub> = ${f(Pd,1)} kN; ratio ${f3(uAx)}`, st2(uAx<=1)],
    ["Section strength, P + M", combos.some(c=>c.hasM)?`ratio ${f3(uSec)}`:"–", combos.some(c=>c.hasM)?"9.3.1":"no moments", combos.some(c=>c.hasM)?st2(uSec<=1):""],
    ["Member buckling, P + M", combos.some(c=>c.hasM)?`ratio ${f3(uMem)}`:"–", combos.some(c=>c.hasM)?"9.3.2.2":"no moments", combos.some(c=>c.hasM)?st2(uMem<=1):""],
    ["Shear", `V = ${f(Math.max(...combos.map(c=>Math.max(c.Vz,c.Vy))),1)} kN`, `ratio ${f3(Math.max(...combos.map(c=>c.uSh)))}`, st2(combos.every(c=>c.uSh<=1))]
  ];
  if(bat){
    const bf=checks.filter(k=>k.group==="Battens" && !k.ok && !k.info);
    sumRows.push({g:"Battens"}, ["Battens", `${v.nBays} bays at ${f(bat.Cs,0)} mm`, `${f(v.bt,0)} mm plates, ${f(v.bdE,0)}/${f(v.bdI,0)} mm deep, ${f(v.wS,0)} mm fillet welds; largest ratio ${f3(batU)}`, st2(!bf.length)]);
  }
  const outcomeRow=["Outcome", allOk?"Column is adequate":"Column is not adequate", `Governing: ${govU[0].toLowerCase()}, ratio ${f3(govU[1])}`, allOk?"PASS":"FAIL"];
  const actions=failed.map(k=>[k.name,k.ref,k.demand,k.capacity,actionFor(k)]);
  return {v,sp,fy,fu,eps,steps,checks,failed,allOk,early:false,inRows,combos,gv,Pd,Pdz,Pdy,Nd,Vdz,Vdy,lz,ly,lz0,ly0,Kz,Ky,bc,FZ,FY,bat,Psw,sumRows,outcomeRow,actions,govU,utils};
}
function actionFor(k){
  const n=strip(k.name);
  if(/slender/i.test(n) && !/component/i.test(n)) return "Use a section with thicker flanges or web.";
  if(/^Slenderness/i.test(n)) return "Add intermediate restraints, or use a section with a larger radius of gyration.";
  if(/axial compression/i.test(n)) return "Use a heavier section, a higher grade, or restrain the column to cut its effective length.";
  if(/section strength/i.test(n)) return "Use a heavier section or a higher steel grade.";
  if(/member buckling/i.test(n)) return "Use a heavier or stiffer section, or add restraints to cut the buckling and lateral-torsional lengths.";
  if(/^.*shear$/i.test(n) && !/batten/i.test(n)) return "Use a section with a thicker web or flanges.";
  if(/bays/i.test(n)) return "Use at least three bays.";
  if(/component slenderness/i.test(n)) return "Add more bays (closer battens).";
  if(/depth/i.test(n)) return "Increase the batten depth to the required value.";
  if(/thickness/i.test(n)) return "Use a thicker batten plate.";
  if(/lap/i.test(n)) return "Increase the lap, or use a thinner plate if the other checks allow.";
  if(/weld size/i.test(n)) return "Change the fillet weld size to suit the plate thickness.";
  if(/weld stress/i.test(n)) return "Use a larger weld, a deeper batten or more bays.";
  if(/batten.*(shear|bending)/i.test(n)) return "Use a deeper or thicker batten, or more bays.";
  return "Revise the design.";
}
function inputRows(v,sp){
  const G=GRADES[v.grade]||GRADES.E250, r=[];
  r.push(["Section", sp?sp.name:(v.sec||"–"), ""]);
  r.push(["Steel grade", G.n, ""]);
  if(v.fam==="SHS"||v.fam==="RHS"||v.fam==="CHS") r.push(["Hollow section", v.hollow==="hot"?"Hot finished":"Cold formed", ""]);
  r.push(["Column length, L", f(v.L,3), "m"]);
  r.push(["z-z end condition", COND[v.condZ][0]+` (K = ${f(kOf(v.condZ,v.Kz),2)})`, ""]);
  r.push(["y-y end condition", COND[v.condY][0]+` (K = ${f(kOf(v.condY,v.Ky),2)})`, ""]);
  r.push(["Unbraced length about y-y", f(v.Ly,3), "m"]);
  r.push(["Effective length for LTB, L_LT", f(v.LLT,3), "m"]);
  r.push(["Sway", v.sway==="yes"?"Free to sway":"Braced (non-sway)", ""]);
  r.push(["Slenderness limit (Table 3)", String(v.slim), ""]);
  r.push(["Self weight", v.sw==="yes"?`Included, γf = ${f(v.gSW,2)}`:"Not included", ""]);
  (v.combos||[]).forEach((c,i)=>r.push([`Combination ${i+1}${c.n?": "+c.n:""}`, `P = ${f(c.P,1)} kN; Mz = ${f(c.Mzt,1)} / ${f(c.Mzb,1)}; My = ${f(c.Myt,1)} / ${f(c.Myb,1)} kN·m (top / bottom)`, ""]));
  if(v.fam==="BUILT"){
    r.push(["Arrangement / gap", `${ARR[(sp&&sp.arr)||v.bArr]} / ${f(v.gap,0)} mm`, ""]);
    r.push(["Number of bays", String(v.nBays), ""]);
    r.push(["Batten depth, end / intermediate", `${f(v.bdE,0)} / ${f(v.bdI,0)}`, "mm"]);
    r.push(["Batten thickness / lap", `${f(v.bt,0)} / ${f(v.ov,0)}`, "mm"]);
    r.push(["Fillet weld size", f(v.wS,1), "mm"]);
  }
  return r;
}

if(typeof module!=="undefined") module.exports={SECTIONS,design,secProps,rolledProps,gapFor,fcdOf,c1Of,classify};
